// Autogenerated, identity-hiding handle for an executor: «прилагательное +
// животное», e.g. «Мудрый Барсук» / «Мудрая Сова». The customer sees this
// instead of the executor's real name. Russian adjectives agree with the
// noun's grammatical gender, so animals carry a gender tag and adjectives
// keep both forms; the generator pairs the matching form.
//
// Pure (takes a `rand` fn) so it's testable and the Convex mutation can pass
// `Math.random`; the DB-side uniqueness retry lives in the executors mutation.
//
// An admin can also override the generated handle with free text (see
// `executors.adminSetNickname`), so this module owns the normalisation and
// validation rules the server enforces and the admin form mirrors.

import { NICKNAME_MAX_LENGTH, NICKNAME_MIN_LENGTH } from './constants'

type Gender = 'm' | 'f'

interface Animal {
  noun: string
  gender: Gender
}

/** Adjective in masculine + feminine forms (nominative singular). */
interface Adjective {
  m: string
  f: string
}

export const NICKNAME_ANIMALS: readonly Animal[] = [
  { noun: 'Барсук', gender: 'm' },
  { noun: 'Ёж', gender: 'm' },
  { noun: 'Бобр', gender: 'm' },
  { noun: 'Филин', gender: 'm' },
  { noun: 'Волк', gender: 'm' },
  { noun: 'Соболь', gender: 'm' },
  { noun: 'Тигр', gender: 'm' },
  { noun: 'Кот', gender: 'm' },
  { noun: 'Лось', gender: 'm' },
  { noun: 'Крот', gender: 'm' },
  { noun: 'Хорёк', gender: 'm' },
  { noun: 'Заяц', gender: 'm' },
  { noun: 'Дельфин', gender: 'm' },
  { noun: 'Пингвин', gender: 'm' },
  { noun: 'Орёл', gender: 'm' },
  { noun: 'Ястреб', gender: 'm' },
  { noun: 'Сова', gender: 'f' },
  { noun: 'Лиса', gender: 'f' },
  { noun: 'Рысь', gender: 'f' },
  { noun: 'Выдра', gender: 'f' },
  { noun: 'Белка', gender: 'f' },
  { noun: 'Панда', gender: 'f' },
  { noun: 'Куница', gender: 'f' },
  { noun: 'Цапля', gender: 'f' },
]

export const NICKNAME_ADJECTIVES: readonly Adjective[] = [
  { m: 'Мудрый', f: 'Мудрая' },
  { m: 'Быстрый', f: 'Быстрая' },
  { m: 'Точный', f: 'Точная' },
  { m: 'Спокойный', f: 'Спокойная' },
  { m: 'Внимательный', f: 'Внимательная' },
  { m: 'Надёжный', f: 'Надёжная' },
  { m: 'Смелый', f: 'Смелая' },
  { m: 'Ловкий', f: 'Ловкая' },
  { m: 'Учёный', f: 'Учёная' },
  { m: 'Дотошный', f: 'Дотошная' },
  { m: 'Бодрый', f: 'Бодрая' },
  { m: 'Хитрый', f: 'Хитрая' },
  { m: 'Чуткий', f: 'Чуткая' },
  { m: 'Стойкий', f: 'Стойкая' },
  { m: 'Зоркий', f: 'Зоркая' },
  { m: 'Умелый', f: 'Умелая' },
  { m: 'Пытливый', f: 'Пытливая' },
  { m: 'Толковый', f: 'Толковая' },
]

/** Total distinct handles the word lists can produce (collision headroom). */
export const NICKNAME_COMBINATIONS = NICKNAME_ANIMALS.length * NICKNAME_ADJECTIVES.length

/** Trim + collapse inner runs of whitespace: `« Мудрый   Барсук »` → `«Мудрый Барсук»`. */
export function normalizeNickname(raw: string): string {
  return raw.trim().replace(/\s+/g, ' ')
}

/**
 * Comparison key for uniqueness. Case-insensitive so «мудрый барсук» can't
 * shadow «Мудрый Барсук» — two handles that read the same to a customer must
 * not coexist.
 */
export function nicknameKey(nickname: string): string {
  return normalizeNickname(nickname).toLowerCase()
}

/**
 * Length bounds + no Unicode control/format characters, after normalization.
 * Deliberately loose otherwise: the admin's free-text override may be any
 * readable handle, not just an «Прилагательное Животное» pair.
 */
export function isValidNickname(raw: string): boolean {
  const value = normalizeNickname(raw)
  if (value.length < NICKNAME_MIN_LENGTH || value.length > NICKNAME_MAX_LENGTH) return false
  return !/\p{C}/u.test(value)
}

/**
 * One random «Прилагательное Животное» handle with correct gender agreement.
 * `rand` defaults to `Math.random`; pass a seeded fn in tests.
 */
export function randomNickname(rand: () => number = Math.random): string {
  const animal = NICKNAME_ANIMALS[Math.floor(rand() * NICKNAME_ANIMALS.length)]
  const adjective = NICKNAME_ADJECTIVES[Math.floor(rand() * NICKNAME_ADJECTIVES.length)]
  // Unreachable in practice — both lists are non-empty constants and the index
  // is always in range — but `noUncheckedIndexedAccess` can't see that, and a
  // real handle beats an assertion if `rand` ever misbehaves.
  if (!animal || !adjective) return 'Мудрый Барсук'
  return `${adjective[animal.gender]} ${animal.noun}`
}
